:root {
  --color-bg: #1a1a2e;
  --color-card: #16213e;
  --color-primary: #e94560;
  --color-secondary: #0f3460;
  --color-text: #eaeaea;
  --color-accent: #f5c542;
  --font-base: 18px;
  --border-width: 4px;
  --shadow-offset: 6px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--color-bg);
  font-family: 'Courier New', Courier, monospace;
  font-size: var(--font-base);
  color: var(--color-text);
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 1rem;
  line-height: 1.5;
}

.calculator {
  background-color: var(--color-card);
  border: var(--border-width) solid var(--color-primary);
  box-shadow: var(--shadow-offset) var(--shadow-offset) 0 var(--color-secondary);
  padding: 2rem;
  width: 100%;
  max-width: 500px;
  image-rendering: pixelated;
}

h1 {
  font-size: 1.8rem;
  text-align: center;
  margin-bottom: 2rem;
  color: var(--color-accent);
  text-transform: uppercase;
  letter-spacing: 2px;
  text-shadow: 3px 3px 0 var(--color-secondary);
}

.field {
  margin-bottom: 1.5rem;
}

label {
  display: block;
  margin-bottom: 0.5rem;
  font-weight: bold;
  color: var(--color-accent);
}

input {
  width: 100%;
  padding: 0.75rem;
  font-family: inherit;
  font-size: 1rem;
  background-color: var(--color-bg);
  border: var(--border-width) solid var(--color-secondary);
  color: var(--color-text);
  outline: none;
}

input:focus-visible {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px var(--color-accent);
}

button {
  width: 100%;
  padding: 1rem;
  font-family: inherit;
  font-size: 1.2rem;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 2px;
  background-color: var(--color-primary);
  color: var(--color-bg);
  border: var(--border-width) solid var(--color-accent);
  box-shadow: var(--shadow-offset) var(--shadow-offset) 0 var(--color-secondary);
  cursor: pointer;
  transition: transform 0.1s, box-shadow 0.1s;
}

button:hover {
  background-color: var(--color-accent);
  color: var(--color-bg);
}

button:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 3px;
}

button:active {
  transform: translate(var(--shadow-offset), var(--shadow-offset));
  box-shadow: none;
}

.results {
  margin-top: 2rem;
  padding-top: 1.5rem;
  border-top: var(--border-width) dashed var(--color-secondary);
}

h2 {
  font-size: 1.4rem;
  margin-bottom: 1rem;
  color: var(--color-accent);
  text-transform: uppercase;
}

.result-item {
  display: flex;
  justify-content: space-between;
  padding: 0.5rem 0;
  border-bottom: 2px solid var(--color-secondary);
}

.result-label {
  font-weight: bold;
}

.result-value {
  font-weight: bold;
  color: var(--color-accent);
}

.error {
  color: var(--color-primary);
  font-weight: bold;
  margin-top: 1rem;
  text-align: center;
}

.footer {
  margin-top: 2rem;
  text-align: center;
  font-size: 0.9rem;
  color: var(--color-secondary);
}

@media (max-width: 400px) {
  .calculator {
    padding: 1.5rem;
  }
  h1 {
    font-size: 1.5rem;
  }
  button {
    font-size: 1rem;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('loan-form');
  const loanAmountInput = document.getElementById('loan-amount');
  const interestRateInput = document.getElementById('interest-rate');
  const loanYearsInput = document.getElementById('loan-years');
  const monthlyPaymentEl = document.getElementById('monthly-payment');
  const totalPaidEl = document.getElementById('total-paid');
  const totalInterestEl = document.getElementById('total-interest');
  const errorMessageEl = document.getElementById('error-message');

  function calculateLoan(principal, annualRate, years) {
    const monthlyRate = annualRate / 100 / 12;
    const numberOfPayments = years * 12;
    let monthlyPayment;

    if (monthlyRate === 0) {
      monthlyPayment = principal / numberOfPayments;
    } else {
      monthlyPayment = principal * monthlyRate * Math.pow(1 + monthlyRate, numberOfPayments) / (Math.pow(1 + monthlyRate, numberOfPayments) - 1);
    }

    const totalPaid = monthlyPayment * numberOfPayments;
    const totalInterest = totalPaid - principal;

    return { monthlyPayment, totalPaid, totalInterest };
  }

  function formatCurrency(value) {
    return value.toFixed(2);
  }

  function displayResults(principal, annualRate, years) {
    const { monthlyPayment, totalPaid, totalInterest } = calculateLoan(principal, annualRate, years);
    monthlyPaymentEl.textContent = '$' + formatCurrency(monthlyPayment);
    totalPaidEl.textContent = '$' + formatCurrency(totalPaid);
    totalInterestEl.textContent = '$' + formatCurrency(totalInterest);
  }

  function showError(message) {
    errorMessageEl.textContent = message;
    errorMessageEl.hidden = false;
    monthlyPaymentEl.textContent = '—';
    totalPaidEl.textContent = '—';
    totalInterestEl.textContent = '—';
  }

  function clearError() {
    errorMessageEl.textContent = '';
    errorMessageEl.hidden = true;
  }

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    clearError();

    const principal = parseFloat(loanAmountInput.value);
    const annualRate = parseFloat(interestRateInput.value);
    const years = parseFloat(loanYearsInput.value);

    if (isNaN(principal) || principal <= 0) {
      showError('Please enter a valid loan amount greater than 0.');
      return;
    }
    if (isNaN(annualRate) || annualRate < 0) {
      showError('Please enter a valid interest rate (0 or greater).');
      return;
    }
    if (isNaN(years) || years <= 0) {
      showError('Please enter a valid loan term in years greater than 0.');
      return;
    }

    displayResults(principal, annualRate, years);
  });
});
